// Thu thập dữ liệu cần sao lưu & tạo tên tệp theo ngày
const dateStr = new Date().toISOString().slice(0, 10).replace(/-/g, '');
const backupFileName = `datphu_backup_${dateStr}_0200.sql.gz`;

// Giả lập kích thước và checksum SHA256 an toàn
const mockSizeMB = (12.4 + Math.random() * 0.8).toFixed(2);
const mockChecksum = 'sha256_' + Math.random().toString(36).substring(2, 15);

return [{
  json: {
    backupFileName: backupFileName,
    storageTarget: 'Cloudflare R2 Bucket (datphu-cold-storage)',
    sizeMB: mockSizeMB + ' MB',
    checksum: mockChecksum,
    status: 'VERIFIED_SUCCESS',
    backupTime: new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' }),
    retentionDays: 90
  }
}];
